#include <bits/stdc++.h>
using namespace std;
#define MOD_CONST 1000000007
typedef unsigned long long ull_type;

struct Matrix {
    ull_type data[35][35];
    int size;
    friend Matrix operator*(const Matrix &A, const Matrix &B) {
        Matrix C;
        C.size = A.size;
        for (int i = 0; i < A.size; ++i) {
            for (int j = 0; j < A.size; ++j) {
                C.data[i][j] = 0;
                for (int k = 0; k < A.size; ++k) {
                    C.data[i][j] += A.data[i][k] * B.data[k][j];
                }
                C.data[i][j] %= MOD_CONST;
            }
        }
        return C;
    }
};

int main() {
    ull_type n_input, m_input;
    cin >> n_input >> m_input;
    Matrix baseMat, identityMat;
    baseMat.size = m_input + 1;
    for (int i = 0; i <= m_input; ++i) {
        baseMat.data[i][i] = 1;
        baseMat.data[0][i] = 1;
    }
    identityMat.size = m_input + 1;
    for (int i = 0; i <= m_input; ++i) {
        identityMat.data[i][i] = 1;
    }

    ull_type yVal = 1, yPow = 1, levelIdx = 0, totalCount = 0;
    while (yPow * m_input <= n_input) {
        yPow *= m_input;
        ++levelIdx;
    }

    vector<vector<Matrix>> biMatrices(levelIdx + 1, vector<Matrix>(m_input + 1));
    for (int t = 0; t <= levelIdx; ++t) {
        if (t > 0) {
            biMatrices[t][0] = biMatrices[t - 1][0];
            for (int i = 1; i <= m_input; ++i) {
                biMatrices[t][0] = biMatrices[t][0] * biMatrices[t - 1][i];
            }
        }
        for (int i = 1; i <= m_input; ++i) {
            biMatrices[t][i] = biMatrices[t][i - 1];
            for (int j = m_input - 2; j >= 0; --j) {
                for (int k = 0; k <= m_input; ++k) {
                    swap(biMatrices[t][i].data[j][k], biMatrices[t][i].data[j + 1][k]);
                }
            }
            for (int j = m_input - 2; j >= 0; --j) {
                for (int k = 0; k <= m_input; ++k) {
                    swap(biMatrices[t][i].data[k][j], biMatrices[t][i].data[k][j + 1]);
                }
            }
        }
    }

    Matrix currentMat = identityMat;
    while (totalCount < n_input) {
        if (totalCount + yPow <= n_input) {
            totalCount += yPow;
            currentMat = currentMat * biMatrices[levelIdx][0];
            yVal = (yVal + 1) % m_input;
        } else {
            yPow /= m_input;
            --levelIdx;
        }
    }

    ull_type finalSum = 0;
    for (int i = 0; i <= m_input; ++i) {
        finalSum = (finalSum + currentMat.data[i][m_input]) % MOD_CONST;
    }
    cout << finalSum << "\n";
}
